	*(*Delimiter)(unsafe.Pointer((*Stack)(unsafe.Pointer(stack)).Fcontents + uintptr(v5))) = int8(v7)
	v1 = stack
	new_size = (*Array)(unsafe.Pointer(v1)).Fsize + uint32(1)
